def tax_role(pricing_quote: dict, tax_rate_bps: int) -> dict:
    net = int(pricing_quote['net_cents'])
    tax_cents = (net * int(tax_rate_bps)) // 10000
    tr01_role_verdicts = [
        {'trace_id': 'tr-01', 'role': 'finite_obstruction', 'e1': 1, 'e2': 1, 'eg': 0},
        {'trace_id': 'tr-01', 'role': 'action_and_alignment', 'e1': 1, 'e2': 1, 'eg': 1},
    ]
    return {
        'taxable_base_cents': net,
        'tax_cents': tax_cents,
        'gross_after_tax_cents': net + tax_cents,
        'tr01_role_verdicts': tr01_role_verdicts,
    }

